const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el asistente de preparación de sesiones de mentoría de RAX.\nTu misión es preparar un Briefing estructurado para el mentor antes de la sesión.\nREGLAS:\n1. Analiza los cambios desde la última sesión y el avance en los objetivos acordados.\n2. Formula de 3 a 5 preguntas potentes y abiertas para el mentor.\n3. Señala decisiones pendientes o bloqueos que requieren atención.\n4. Si no hay registros de un hecho, no lo asumas.\n5. Salida en JSON estricto con los campos: sessionGoal (string), currentStatusSummary (string), agendaTopics (array de strings), suggestedQuestions (array de strings), pendingDecisions (array de strings), uncertainties (array de strings).`;

const userPrompt = JSON.stringify({
  projectId: event.projectId,
  sessionKind: payload.sessionKind || 'follow_up',
  goals: payload.goals || [],
  previousNotes: payload.previousNotes || [],
  recentEvidence: payload.recentEvidence || [],
  pendingTasks: payload.pendingTasks || []
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'http://localhost:3000') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    systemPrompt,
    userPrompt
  }
}];

const response = $input.first().json;
const prep = $('Build Session Prep Prompt').first().json;

let parsed = {};
try {
  const content = response.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = {
    sessionGoal: 'Revisión general de avances y acuerdos',
    agendaTopics: ['Revisión de compromisos anteriores'],
    uncertainties: ['Salida de modelo no estructurada']
  };
}

const proposals = (parsed.agendaTopics || []).map(topic => ({
  type: 'agenda_topic',
  title: topic,
  needsHumanApproval: true,
  uncertainties: []
}));

const callbackPayload = {
  operationId: 'op_prep_' + Date.now(),
  correlationId: prep.correlationId,
  workflowId: 'RAX-05',
  workflowVersion: '1.0.0',
  status: 'completed',
  usage: {
    model: response.model || prep.model,
    promptTokens: response.usage?.prompt_tokens || 0,
    completionTokens: response.usage?.completion_tokens || 0
  },
  data: {
    summary: parsed.currentStatusSummary || parsed.sessionGoal,
    proposals,
    rawOutput: parsed,
    uncertainties: parsed.uncertainties || [],
    nextStepRecommendation: (parsed.suggestedQuestions || []).join(' | ')
  }
};

return [{
  json: {
    callbackUrl: prep.callbackUrl,
    payload: callbackPayload
  }
}];
